    case .rug: [1.192, 1.192, 0.098]
    case .catbed: [0.497, 0.5, 0.15]
    }
  }

  /// How much of its bounding box the cat must keep off: a round thing fills less of it.
  var footprint: Float {
    switch self {
    case .beanbag, .monstera, .cactus, .mugs, .stringlights, .rug, .catbed: 0.85
