extension GenzPiece.Kind {
  /// The generated prop's kind for its shop item, `furniture-idol-<raw value>`, or nil for any
  /// other item.
  init?(shopItem id: String) {
    let prefix = "furniture-idol-"
    guard id.hasPrefix(prefix), let prop = IdolProp(rawValue: String(id.dropFirst(prefix.count)))
    else { return nil }
    self = prop.kind
  }
}
